#!/usr/bin/env bash
# Some portions generated by Codex
set -euo pipefail

usage() {
  cat <<'EOF'
Measure an existing LMDB repository from construction through readiness.

Usage: scripts/lmdb-startup-acceptance.sh --store DIRECTORY [options]
  --copy-to DIRECTORY          Create a new retained copy before opening it.
  --triple-indexes SPECS        Request a background statement layout change.
  --triple-term-indexes SPECS   Request a background triple-term layout change.
  --config FILE                Apply an existing Turtle repository/Sail configuration.
  --max-ready-ms MILLISECONDS  Optional timing assertion (default: no timing assertion).
  --output FILE                Result JSON (default: a new file under logs/).

The supplied repository must be closed. Ordinary startup writes metadata and
background maintenance may update derived indexes. Use --copy-to to preserve
the original. This runner never creates a dataset or deletes its retained copy.
EOF
}

repo_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
store_directory=
copy_directory=
statement_indexes=
term_indexes=
max_ready_ms=
configuration_file=
output_file=
while (($#)); do
  case "$1" in
    --store|--copy-to|--triple-indexes|--triple-term-indexes|--max-ready-ms|--output|--config)
      if (($# < 2)); then usage >&2; exit 2; fi
      case "$1" in
        --store) store_directory=$2 ;;
        --copy-to) copy_directory=$2 ;;
        --triple-indexes) statement_indexes=$2 ;;
        --triple-term-indexes) term_indexes=$2 ;;
        --max-ready-ms) max_ready_ms=$2 ;;
        --output) output_file=$2 ;;
        --config) configuration_file=$2 ;;
      esac
      shift 2
      ;;
    --help|-h) usage; exit 0 ;;
    *) usage >&2; exit 2 ;;
  esac
done
if [[ -z "$store_directory" || ! -f "$store_directory/store.properties" || ! -f "$store_directory/values/data.mdb" || ! -f "$store_directory/triples/data.mdb" ]]; then
  printf '%s\n' '--store must name an existing, closed RDF4J LMDB repository.' >&2
  exit 2
fi
store_directory=$(cd "$store_directory" && pwd)
if [[ -n "$configuration_file" ]]; then
  if [[ ! -f "$configuration_file" ]]; then
    printf '%s\n' '--config must name an existing Turtle configuration file.' >&2
    exit 2
  fi
  configuration_file="$(cd "$(dirname "$configuration_file")" && pwd)/$(basename "$configuration_file")"
fi
if [[ -n "$copy_directory" ]]; then
  if [[ -e "$copy_directory" ]]; then
    printf '%s\n' '--copy-to must name a new directory; existing files are never overwritten.' >&2
    exit 2
  fi
  mkdir -p "$copy_directory"
  cp -R "$store_directory/." "$copy_directory/"
  store_directory=$(cd "$copy_directory" && pwd)
fi
cd "$repo_root"
mkdir -p logs
if [[ -z "$output_file" ]]; then
  output_file="$repo_root/logs/lmdb-startup-acceptance-$(date +%Y%m%d-%H%M%S)-$$.json"
elif [[ "$output_file" != /* ]]; then
  output_file="$repo_root/$output_file"
fi
if [[ -e "$output_file" ]]; then
  printf '%s\n' 'The result file already exists; choose a new --output path.' >&2
  exit 2
fi
test_args=("-Drdf4j.lmdb.startup.acceptance.store=$store_directory" "-Drdf4j.lmdb.startup.acceptance.output=$output_file")
if [[ -n "$configuration_file" ]]; then test_args+=("-Drdf4j.lmdb.startup.acceptance.config=$configuration_file"); fi
if [[ -n "$statement_indexes" ]]; then test_args+=("-Drdf4j.lmdb.startup.acceptance.tripleIndexes=$statement_indexes"); fi
if [[ -n "$term_indexes" ]]; then test_args+=("-Drdf4j.lmdb.startup.acceptance.termIndexes=$term_indexes"); fi
if [[ -n "$max_ready_ms" ]]; then test_args+=("-Drdf4j.lmdb.startup.acceptance.maxReadyMillis=$max_ready_ms"); fi
printf 'Opening supplied repository with ordinary metadata writes: %s\n' "$store_directory"
python3 .codex/skills/mvnf/scripts/mvnf.py LmdbStartupAcceptanceTest --retain-logs -- "${test_args[@]}"
printf 'Acceptance result: %s\n' "$output_file"
